"""Verify this progress snapshot, explicitly not the full research objective."""
import pathlib,json,hashlib,datetime
R=pathlib.Path(__file__).resolve().parents[1];B=R.parent;O=R/'outputs';out=O/'SNAPSHOT_CLOSURE.json';assert not out.exists();read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'));sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();checks=[]
def check(name,value):assert value,name;checks.append(name)
stop=read(B/'cycle44/outputs/EARLY_STOP_DECISION.json');receipt=read(B/'cycle44/outputs/PROCESS_STOP_RECEIPT.json');partial=read(B/'cycle44/outputs/query_analysis_partial_v1/analysis_summary.json');check('recorded_research_stop_not_full_completion',stop['decision']=='STOP_REMAINING_QUERY_POOLS_LOW_INFORMATION' and not stop['full_query_experiment_completed'] and receipt['status']=='STOPPED_BY_RESEARCH_PRIORITY');check('partial_scoring_explicitly_incomplete',partial['status']=='SCORING_VERIFIED_FOR_COMPLETED_SUBSET' and not partial['full_original_protocol_completed'] and partial['models']==5 and partial['rows']==972 and partial['raw_npz_files_SHA_checked']==340);check('stop_decision_bound_to_partial_scores',partial['stop_decision_sha256']==sha(B/'cycle44/outputs/EARLY_STOP_DECISION.json'));check('no_full_query_summary_claim',not (B/'cycle44/outputs/query_execution_v1/execution_summary.json').exists())
for item in stop['completed_query_models']:check('retained_completed_model_'+item['model'],sha(B/'cycle44/outputs/query_execution_v1'/item['model']/'execution.json')==item['execution_sha256'])
q=read(O/'native_qualification_v1/qualification.json');v=read(O/'verification_v1.json');check('native_qualification_verified',q['status']=='PASS_WITH_EXPLICIT_SAMPLING_CONTRACTS' and v['status']=='PASS' and v['qualification_sha256']==sha(O/'native_qualification_v1/qualification.json'));check('only_discarded_preflight_training',q['nonlinear_discarded_updates']==10 and q['comparative_effects']==0 and not q['GPU_initialized']);check('raw_linear_samples_retained',sha(O/'native_qualification_v1/linear_sampling.npz')==q['sampling_arrays_sha256']==v['raw_sampling_sha256']);check('discarded_checkpoint_retained',sha(O/'native_qualification_v1/discarded_preflight.pt')==q['discarded_checkpoint_sha256']==v['checkpoint_sha256']);source=read(R/'source_archive/ncdssm/SOURCE_TREE.json')
for f in source['files']:check('source_'+f['path'],sha(R/'source_archive/ncdssm'/f['path'])==f['sha256'])
for folder in [B/'cycle44',R]:
 manifest=read(folder/'REPORT_MANIFEST.json');check(folder.name+'_goal_unachieved',manifest['goal']=='ACTIVE_UNACHIEVED' and manifest['accepted_final_directions']==0)
 for name,digest in manifest['reports'].items():check(folder.name+'_report_'+name,sha(folder/name)==digest)
qa=read(O/'figures_v1/visual_qa.json');check('visual_qa_completed',qa['status']=='PASS')
for name,digest in qa['files'].items():check('figure_'+name,sha(O/'figures_v1'/name)==digest)
indices=read(R/'ROOT_INDEX_RECEIPTS.json')
for item in indices['files']:check('root_index_'+item['path'],sha(B/item['path'])==item['sha256'])
result={'status':'EVIDENCE_SNAPSHOT_VERIFIED_GOAL_UNACHIEVED','utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'checks':checks,'original_C44_query_protocol_complete':False,'completed_query_subset_models':5,'native_C45_discarded_updates':10,'new_framework_comparative_effects':0,'accepted_final_directions':0,'goal':'ACTIVE_UNACHIEVED','required_remaining':['ordinary nonlinear generative joint-path baseline with explicit outer-history draws','a concrete distinct learning interaction beyond complete direct combinations','fresh held-out mechanism evidence and independent tasks/domains','verified novelty and final research direction'],'source_sha256':sha(pathlib.Path(__file__))};out.write_text(json.dumps(result,indent=2),encoding='utf-8');print(json.dumps({'status':result['status'],'artifact_checks':len(checks),'accepted_final_directions':0,'goal':'ACTIVE_UNACHIEVED'}))
